const TEAM_MODES = [['alias','Alias'],['charades','Charades'],['taboo','Taboo']];
const SOLO_MODES = [['cards','Flashcards'],['quiz','Quick Quiz'],['blocks','Blocks'],['match','Match'],['gravity','Gravity']];
const MODES = TEAM_MODES.concat(SOLO_MODES);
const $ = s => document.querySelector(s);
const shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
function save(k, v){ try{ localStorage.setItem('ifarena:'+k, JSON.stringify(v)); }catch(e){} }
function load(k, d){ try{ const v = localStorage.getItem('ifarena:'+k); return v ? JSON.parse(v) : d; }catch(e){ return d; } }
function esc(s){ return String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
const findKey = h => Object.keys(DATA).find(k => k.toLowerCase() === h.toLowerCase());
let lesson = findKey((location.hash || '').replace('#','')) || load('lesson', Object.keys(DATA)[0]);
if (!DATA[lesson]) lesson = Object.keys(DATA)[0];
let mode = load('mode', 'alias');
if (!MODES.some(m => m[0] === mode)) mode = 'alias';
const st = { teams:[{name:'Team A',pts:0},{name:'Team B',pts:0}], turn:0, time:60, timer:null, deck:[], cur:null, running:false, hint:false };
let fc = { i:0, list:[], known:0, lesson:null }, qz = null, bk = null, mt = null, gv = null;
let loop = { iv:null, raf:null };
function stopLoops(){ clearInterval(st.timer); clearInterval(loop.iv); cancelAnimationFrame(loop.raf); loop = { iv:null, raf:null }; st.running = false; }
function chips(){
  const L = $('#lessons'), M = $('#modes');
  L.querySelectorAll('button').forEach(b => b.remove()); M.innerHTML = '';
  Object.keys(DATA).forEach(k => { const b = document.createElement('button'); b.textContent = k + ' · ' + DATA[k].title; b.className = k === lesson ? 'on' : ''; b.setAttribute('aria-pressed', k === lesson); b.onclick = () => { lesson = k; save('lesson', k); qz = bk = mt = gv = null; reset(); }; L.appendChild(b); });
  const group = (label, list) => { const sp = document.createElement('span'); sp.className = 'lbl'; sp.textContent = label; M.appendChild(sp);
    list.forEach(([k, n]) => { const b = document.createElement('button'); b.textContent = n; b.className = k === mode ? 'on' : ''; b.setAttribute('aria-pressed', k === mode); b.onclick = () => { mode = k; save('mode', k); qz = bk = mt = gv = null; reset(); }; M.appendChild(b); }); };
  group('Teams', TEAM_MODES); const sep = document.createElement('span'); sep.className = 'sep'; M.appendChild(sep); group('Solo', SOLO_MODES);
}
function reset(){ stopLoops(); st.deck = shuffle(DATA[lesson].words); st.over = false; st.time = 60; st.hint = false; chips(); render(); }
function next(){ if (!st.deck.length) return false; st.cur = st.deck.pop(); st.hint = false; return true; }
function render(){ ({alias:team, charades:team, taboo:team, cards:flash, quiz:quiz, blocks:blocks, match:match, gravity:gravity})[mode](); }
const words = () => DATA[lesson].words;
function mcq(q){ return shuffle([q].concat(shuffle(words().filter(w => w !== q)).slice(0,3))); }

